function normalizeAdzunaItem(raw) {
    return {
      source: 'adzuna.ch',
      source_id: raw.id,
      title: raw.title,
      company: raw.company ? raw.company.display_name : null,
      url: raw.redirect_url,
      location: raw.location ? raw.location.display_name : null,
      posted_at: raw.created ? raw.created.slice(0, 10) : null,
      raw_extra: {
        description_snippet: raw.description || null,
        salary_min: raw.salary_min || null,
        salary_max: raw.salary_max || null,
        contract_type: raw.contract_type || null,
        contract_time: raw.contract_time || null,
        category: raw.category ? raw.category.label : null,
        description_full: raw.fullDescription || null,
      },
    };
  }

  const input = items[0].json;

  if (!input || !Array.isArray(input.results)) {
    // La requête a échoué (Continue On Fail) ou n'a pas la forme attendue — on log et on ne fait rien planter.
    console.log('Adzuna: pas de résultats exploitables', JSON.stringify(input));
    return [];
  }

  return input.results.map(item => ({ json: normalizeAdzunaItem(item) }));

function normalizeJoobleItem(raw) {
    return {
      source: 'jooble.ch',
      source_id: raw.id,
      title: raw.title,
      company: raw.company || null,
      url: raw.link,
      location: raw.location || null,
      posted_at: raw.updated ? raw.updated.slice(0, 10) : null,
      raw_extra: {
        description_snippet: raw.snippet || null,
        salary: raw.salary || null,
        type: raw.type || null,
        source_name: raw.source || null,
        description_full: raw.fullDescription || null,
      },
    };
  }

  const input = items[0].json;

  if (!input || !Array.isArray(input.jobs)) {
    console.log('Jooble: input inattendu', JSON.stringify(input));
    return [];
  }

  return input.jobs.map(item => ({ json: normalizeJoobleItem(item) }));

const html = items[0].json.data;
  const pattern = new RegExp('<script type="application/ld\\+json">(.*?)<\\/script>', 's');
  const match = html.match(pattern);
  if (!match) return [];

  const ldJson = JSON.parse(match[1]);
  const itemList = ldJson.find(entry => entry['@type'] === 'ItemList');
  if (!itemList) return [];

  return itemList.itemListElement.map(entry => {
    const job = entry.item;
    return {
      json: {
        id: job.identifier ? job.identifier.value : null,
        title: job.title,
        company: job.hiringOrganization ? job.hiringOrganization.name : null,
        url: job.url,
        location: job.jobLocation && job.jobLocation.address ? job.jobLocation.address.addressLocality
  || null : null,
        postedDate: job.datePosted ? job.datePosted.slice(0, 10) : null,
        contractType: job.employmentType || null,
        remote: null,
        description: job.description || null,
      },
    };
  });

function normalizeJobchListing(raw) {
    return {
      source: 'jobs.ch',
      source_id: raw.id,
      title: raw.title,
      company: raw.company,
      url: raw.url,
      location: raw.location,
      posted_at: raw.postedDate || null,
      raw_extra: {
        contract_type: raw.contractType || null,
        remote: raw.remote || null,
        description: raw.description || null,
      },
    };
  }

  return items.map(item => ({ json: normalizeJobchListing(item.json) }));

const FRENCH_WORDS = ['et', 'le', 'la', 'les', 'des', 'pour', 'avec', 'notre', 'nos', 'vous', 'êtes',
  'nous', 'recherchons', 'poste', 'équipe', 'expérience', 'compétences'];
  const GERMAN_WORDS = ['und', 'der', 'die', 'das', 'mit', 'für', 'sind', 'werden', 'sie', 'ihre',
  'unsere', 'kenntnisse', 'erfahrung', 'aufgaben', 'wir', 'suchen', 'stelle', 'unternehmen'];
  const ITALIAN_WORDS = ['e', 'il', 'la', 'di', 'per', 'con', 'sono', 'nostra', 'nostro', 'esperienza',
  'competenze', 'cerchiamo', 'azienda', 'lavoro'];
  const ENGLISH_WORDS = ['the', 'and', 'you', 'our', 'for', 'with', 'are', 'will', 'team', 'looking',
  'join', 'experience', 'skills', 'role', 'we'];

  function buildMarker(words) {
    return new RegExp('\\b(' + words.join('|') + ')\\b', 'gi');
  }

  const FRENCH_MARKERS = buildMarker(FRENCH_WORDS);
  const GERMAN_MARKERS = buildMarker(GERMAN_WORDS);
  const ITALIAN_MARKERS = buildMarker(ITALIAN_WORDS);
  const ENGLISH_MARKERS = buildMarker(ENGLISH_WORDS);

  const LOCATION_ALIASES = {
    'genève': ['genève', 'geneva', 'genf', 'ginevra'],
    'lausanne': ['lausanne', 'losanna'],
    'neuchâtel': ['neuchâtel', 'neuenburg', 'neuchatel'],
  };

  const EXPANDED_KEYWORDS = ['database engineer', 'data architect', 'analytics engineer', 'data ops',
  'platform engineer', 'site reliability engineer', 'sre', 'cloud engineer', 'infrastructure engineer'];

  const JUNIOR_WORDS = ['junior', 'intern', 'internship', 'graduate', 'entry-level', 'entry level'];

  function searchableText(listing) {
    return [
      listing.title || '',
      listing.raw_extra && (listing.raw_extra.description || listing.raw_extra.description_snippet ||
  listing.raw_extra.description_full) || '',
    ].join(' ').toLowerCase();
  }

  function locationMatches(listing, profile) {
    const location = (listing.location || '').toLowerCase();
    if (!location) return false;
    return profile.locations.some((loc) => {
      const locLower = loc.toLowerCase();
      const aliases = LOCATION_ALIASES[locLower] || [locLower];
      return aliases.some(alias => location.includes(alias));
    });
  }

  function detectForeignLanguage(listing) {
    const text = searchableText(listing);
    const counts = {
      fr: (text.match(FRENCH_MARKERS) || []).length,
      de: (text.match(GERMAN_MARKERS) || []).length,
      it: (text.match(ITALIAN_MARKERS) || []).length,
      en: (text.match(ENGLISH_MARKERS) || []).length,
    };

    const nonFrenchMax = Math.max(counts.de, counts.it, counts.en);

    if (counts.fr >= 2 && counts.fr >= nonFrenchMax) return null;
    if (nonFrenchMax < 2) return null;

    if (counts.de === nonFrenchMax) return 'de';
    if (counts.it === nonFrenchMax) return 'it';
    return 'en';
  }

  function scoreListing(listing, profile) {
    const text = searchableText(listing);

    const matchedCore = profile.keywords.filter(kw => text.includes(kw.toLowerCase()));
    const matchedExpanded = EXPANDED_KEYWORDS.filter(kw => text.includes(kw));

    if (matchedCore.length === 0 && matchedExpanded.length === 0) return 0;

    let score = matchedCore.length * 3 + matchedExpanded.length * 1;

    const isJunior = JUNIOR_WORDS.some(w => new RegExp(`\\b${w}\\b`, 'i').test(text));
    if (isJunior) score += 2;

    if (locationMatches(listing, profile)) score += 1;

    return score;
  }

  const profile = $('Loop Over Items').first().json;

  return items
    .map(item => {
      const score = scoreListing(item.json, profile);
      const text = searchableText(item.json);
      const keywordsMatched = [...profile.keywords, ...EXPANDED_KEYWORDS].filter(kw =>
  text.includes(kw.toLowerCase()));
      return {
        json: {
          ...item.json,
          matchScore: score,
          matchCategory: score >= 3 ? 'primary' : score >= 1 ? 'secondary' : 'excluded',
          foreignLanguage: detectForeignLanguage(item.json),
          locationIncomplete: !item.json.location,
          keywordsMatched,
          searchProfileId: profile.id,
        },
      };
    })
    .filter(item => item.json.matchCategory !== 'excluded')
    .sort((a, b) => b.json.matchScore - a.json.matchScore);

const original = $('Filter by profile').item.json;
  const translations = $json.translations || [];

  return {
    json: {
      ...original,
      title: translations[0] ? translations[0].text : original.title,
      raw_extra: {
        ...original.raw_extra,
        description_fr: translations[1] ? translations[1].text : null,
        title_original: original.title,
